async function init() {
    const data = await d3.csv("data/stock-descriptions.csv");

    // Preprocess data
    const stocks = data.map(d => ({
        ticker: d.ticker,
        name: d["full name"],
        sector: d.sector || "Unknown",
        marketCap: d.marketCap ? parseFloat(d.marketCap) : null,
        country: d.country,
        website: d.website,
        isETF: !d.marketCap || d.marketCap === "0.0" || d.sector === "ETF" || d.sector === ""
    })).filter(d => d.ticker);

    const displayStocks = stocks.slice(0, 50);

    const formatMarketCap = (val) => {
        if (!val) return "N/A";
        if (val >= 1e12) return (val / 1e12).toFixed(2) + "T";
        if (val >= 1e9) return (val / 1e9).toFixed(2) + "B";
        if (val >= 1e6) return (val / 1e6).toFixed(2) + "M";
        return val.toLocaleString();
    };

    // --- Bubble Chart ---
    const chartContainer = document.getElementById('chart-container');
    const width = chartContainer.clientWidth;
    const height = chartContainer.clientHeight - 60;

    const svg = d3.select("#chart-container")
        .append("svg")
        .attr("viewBox", [0, 0, width, height]);

    const tooltip = d3.select("#tooltip");

    const sectors = Array.from(new Set(displayStocks.map(d => d.sector)));
    const colorScale = d3.scaleOrdinal(d3.schemeCategory10).domain(sectors);

    // Legend
    const legend = d3.select("#chart-container").insert("div", "svg").attr("class", "legend");
    sectors.forEach(sector => {
        const item = legend.append("div").attr("class", "legend-item");
        item.append("div").attr("class", "legend-color").style("background-color", colorScale(sector));
        item.append("span").text(sector);
    });

    const maxCap = d3.max(displayStocks, d => d.marketCap) || 1;
    const radiusScale = d3.scaleSqrt()
        .domain([0, maxCap])
        .range([10, 50]);

    displayStocks.forEach(d => {
        d.radius = d.isETF ? 20 : radiusScale(d.marketCap);
    });

    // Force Simulation
    const sectorClusters = {};
    const angleStep = (2 * Math.PI) / sectors.length;
    sectors.forEach((sector, i) => {
        const angle = i * angleStep;
        const r = Math.min(width, height) * 0.35;
        sectorClusters[sector] = {
            x: width / 2 + r * Math.cos(angle),
            y: height / 2 + r * Math.sin(angle)
        };
    });

    const simulation = d3.forceSimulation(displayStocks)
        .force("x", d3.forceX(d => sectorClusters[d.sector].x).strength(0.15))
        .force("y", d3.forceY(d => sectorClusters[d.sector].y).strength(0.15))
        .force("collide", d3.forceCollide(d => d.radius + 2))
        .force("center", d3.forceCenter(width / 2, height / 2))
        .on("tick", () => {
            node.attr("transform", d => `translate(${d.x},${d.y})`);
        });

    const node = svg.selectAll(".node")
        .data(displayStocks)
        .enter()
        .append("g")
        .attr("class", "node")
        .on("mouseover", (event, d) => {
            if (d.isETF) return;
            tooltip.style("display", "block")
                .html(`<strong>${d.ticker}</strong><br>${d.name}<br>Sector: ${d.sector}`)
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 10) + "px");
        })
        .on("mousemove", (event) => {
            tooltip.style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 10) + "px");
        })
        .on("mouseout", () => {
            tooltip.style("display", "none");
        })
        .on("click", (event, d) => {
            highlightStock(d.ticker);
        });

    node.append("circle")
        .attr("class", "bubble")
        .attr("id", d => `bubble-${d.ticker}`)
        .attr("r", d => d.radius)
        .attr("fill", d => colorScale(d.sector));

    node.append("text")
        .attr("class", "label")
        .attr("dy", ".3em")
        .text(d => d.ticker);

    // --- Data Table ---
    const tableBody = d3.select("#table-container table tbody");
    const rows = tableBody.selectAll("tr")
        .data(displayStocks)
        .enter()
        .append("tr")
        .attr("id", d => `row-${d.ticker}`)
        .on("click", (event, d) => {
            highlightStock(d.ticker);
        });

    rows.append("td").text(d => d.ticker);
    rows.append("td").text(d => d.name);
    rows.append("td").text(d => d.sector);
    rows.append("td").text(d => formatMarketCap(d.marketCap));

    // --- Price History Chart ---
    const priceChartContainer = d3.select("#price-history-chart");
    const priceChartWidth = document.getElementById('price-history-chart').clientWidth;
    const priceChartHeight = document.getElementById('price-history-chart').clientHeight;

    const priceSvg = priceChartContainer.append("svg")
        .attr("viewBox", [0, 0, priceChartWidth, priceChartHeight]);

    const priceMargin = {top: 10, right: 30, bottom: 30, left: 50};
    const priceInnerWidth = priceChartWidth - priceMargin.left - priceMargin.right;
    const priceInnerHeight = priceChartHeight - priceMargin.top - priceMargin.bottom;

    const g = priceSvg.append("g")
        .attr("transform", `translate(${priceMargin.left},${priceMargin.top})`);

    const x = d3.scaleTime().range([0, priceInnerWidth]);
    const y = d3.scaleLinear().range([priceInnerHeight, 0]);

    const line = d3.line()
        .x(d => x(d.date))
        .y(d => y(d.close));

    const xAxis = g.append("g")
        .attr("transform", `translate(0,${priceInnerHeight})`);

    const yAxis = g.append("g");

    const pricePath = g.append("path")
        .attr("fill", "none")
        .attr("stroke", "steelblue")
        .attr("stroke-width", 2);

    async function updatePriceChart(ticker, name) {
        d3.select("#price-history-title").text(`${name} (${ticker}) Price History`);

        try {
            const priceData = await d3.csv(`data/indiv-stock/${ticker}.csv`);
            const parsedData = priceData.map(d => ({
                date: new Date(d.Date),
                close: parseFloat(d.Close) || parseFloat(d["Adjusted Close"])
            })).filter(d => !isNaN(d.date) && !isNaN(d.close));

            x.domain(d3.extent(parsedData, d => d.date));
            y.domain([d3.min(parsedData, d => d.close) * 0.95, d3.max(parsedData, d => d.close) * 1.05]);

            xAxis.transition().call(d3.axisBottom(x).ticks(6));
            yAxis.transition().call(d3.axisLeft(y).ticks(5));

            pricePath
                .datum(parsedData)
                .transition()
                .attr("d", line);
        } catch (e) {
            console.error("Could not load price data for", ticker, e);
            d3.select("#price-history-title").text(`Price history not available for ${ticker}`);
            pricePath.attr("d", "");
        }
    }

    // --- Interaction ---
    function highlightStock(ticker) {
        // Reset highlights
        d3.selectAll(".bubble").classed("highlighted", false);
        d3.selectAll("tr").classed("highlighted", false);

        // Set new highlights
        d3.select(`#bubble-${ticker}`).classed("highlighted", true);
        const selectedRow = d3.select(`#row-${ticker}`);
        selectedRow.classed("highlighted", true);

        // Scroll table to row
        const rowElement = document.getElementById(`row-${ticker}`);
        if (rowElement) {
            rowElement.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }

        const stock = displayStocks.find(d => d.ticker === ticker);
        updatePriceChart(ticker, stock.name);
    }
}

window.addEventListener('load', init);

